        memo = {}

        def dfs(r: int, c: int) -> int:
            if r == m or c == n or matrix[r][c] == "0":
                return 0
            if (r, c) not in memo:
                memo[(r, c)] = 1 + min(dfs(r + 1, c), dfs(r, c + 1), dfs(r + 1, c + 1))
            return memo[(r, c)]

        best = 0
        for r in range(m):
            for c in range(n):
                best = max(best, dfs(r, c))
        return best * best

